     1→// ============================================================================
     2→// FreeLang Replication 모듈 - 쿼럼 기반 복제
     3→// ============================================================================
     4→// 목표: Zero-Copy-DB에서 고가용성을 위한 데이터 복제 구현
     5→// 원리:
     6→//   1. 쿼럼(Quorum) 쓰기: 과반수(factor/2+1) 이상 노드 성공 → 전체 성공
     7→//   2. 복제 상태: ALIVE(정상), SUSPECT(의심), DEAD(다운)
     8→//   3. 하트비트: tick 카운터로 노드 상태 감지
     9→//   4. 내장 KV: 각 노드가 배열 기반 로컬 스토어 보유
    10→// 구조:
    11→//   - 상수 정의 (노드 상태, 복제 파라미터)
    12→//   - ReplicaNode, ReplicaGroup 구조체
    13→//   - 팩토리 함수
    14→//   - 그룹 관리 (node_add, node_remove, alive_count)
    15→//   - 쿼럼 연산 (write_quorum, read_quorum)
    16→//   - 내장 KV 스토어
    17→//   - 하트비트 관리
    18→// ============================================================================
    19→
    20→module replication {
    21→    // === 상수: 노드 상태 ===
    22→    const REPLICA_ALIVE:    i32 = 0;
    23→    const REPLICA_SUSPECT:  i32 = 1;
    24→    const REPLICA_DEAD:     i32 = 2;
    25→
    26→    // === 상수: 복제 파라미터 ===
    27→    const REPLICATION_FACTOR:  i32 = 3;
    28→    const DEFAULT_QUORUM:      i32 = 2;    // factor/2 + 1
    29→    const MAX_NODES:           i32 = 32;
    30→    const MAX_KV_PER_NODE:     i32 = 256;
    31→
    32→    // === 상수: 하트비트 타이머 (tick 단위) ===
    33→    const HEARTBEAT_TIMEOUT:   i32 = 5;    // 5 tick 이상 응답 없으면 SUSPECT
    34→    const SUSPECT_TIMEOUT:     i32 = 3;    // 3 tick 이상이면 DEAD
    35→
    36→    // === 에러 코드 ===
    37→    const REP_OK:              i32 = 0;
    38→    const REP_ERR_QUORUM:      i32 = 10;   // 쿼럼 실패
    39→    const REP_ERR_NO_ALIVE:    i32 = 11;   // 살아있는 노드 없음
    40→    const REP_ERR_NOT_FOUND:   i32 = 12;   // 키를 찾을 수 없음
    41→    const REP_ERR_DUPLICATE:   i32 = 13;   // 중복된 노드
    42→
    43→    // === 데이터 구조체 ===
    44→    // 복제 그룹의 멤버 노드
    45→    struct ReplicaNode {
    46→        id:              string;
    47→        addr:            string;     // "node1:8001" 형태
    48→        state:           i32;        // REPLICA_ALIVE/SUSPECT/DEAD
    49→        last_heartbeat:  i32;        // 마지막 하트비트 tick
    50→
    51→        // 내장 KV 스토어 (배열 기반)
    52→        store_keys:      [string];
    53→        store_vals:      [i64];
    54→        store_count:     i32;
    55→    }
    56→
    57→    // 복제 그룹 (여러 ReplicaNode로 구성)
    58→    struct ReplicaGroup {
    59→        nodes:          [ReplicaNode];
    60→        node_count:     i32;
    61→        quorum:         i32;        // 필요한 최소 응답 수 (보통 factor/2+1)
    62→        factor:         i32;        // 복제 인수 (보통 3)
    63→        current_tick:   i32;        // 현재 tick (하트비트 계산용)
    64→    }
    65→
    66→    // === 팩토리 함수 ===
    67→
    68→    // ReplicaGroup 생성
    69→    func group_new(quorum: i32, factor: i32) -> ReplicaGroup {
    70→        return ReplicaGroup{
    71→            nodes:          make([ReplicaNode], MAX_NODES),
    72→            node_count:     0,
    73→            quorum:         quorum,
    74→            factor:         factor,
    75→            current_tick:   0,
    76→        };
    77→    }
    78→
    79→    // ReplicaNode 생성
    80→    func replica_node_new(id: string, addr: string) -> ReplicaNode {
    81→        return ReplicaNode{
    82→            id:              id,
    83→            addr:            addr,
    84→            state:           REPLICA_ALIVE,
    85→            last_heartbeat:  0,
    86→            store_keys:      make([string], MAX_KV_PER_NODE),
    87→            store_vals:      make([i64], MAX_KV_PER_NODE),
    88→            store_count:     0,
    89→        };
    90→    }
    91→
    92→    // === 그룹 관리 함수 ===
    93→
    94→    // 그룹에 노드 추가
    95→    func (g: *ReplicaGroup) node_add(node: ReplicaNode) -> bool {
    96→        if g.node_count >= MAX_NODES {
    97→            return false;
    98→        }
    99→        // 중복 확인
   100→        let i = 0;
   101→        for i = 0; i < g.node_count; i = i + 1 {
   102→            if g.nodes[i].id == node.id {
   103→                return false;  // 중복 노드
   104→            }
   105→        }
   106→        g.nodes[g.node_count] = node;
   107→        g.node_count = g.node_count + 1;
   108→        return true;
   109→    }
   110→
   111→    // 그룹에서 노드 제거
   112→    func (g: *ReplicaGroup) node_remove(id: string) -> bool {
   113→        let i = 0;
   114→        let j = 0;
   115→        let found = false;
   116→        for i = 0; i < g.node_count; i = i + 1 {
   117→            if g.nodes[i].id != id {
   118→                g.nodes[j] = g.nodes[i];
   119→                j = j + 1;
   120→            } else {
   121→                found = true;
   122→            }
   123→        }
   124→        if found {
   125→            g.node_count = j;
   126→        }
   127→        return found;
   128→    }
   129→
   130→    // 노드 ID로 인덱스 찾기
   131→    func (g: *ReplicaGroup) node_find(id: string) -> (i32, bool) {
   132→        let i = 0;
   133→        for i = 0; i < g.node_count; i = i + 1 {
   134→            if g.nodes[i].id == id {
   135→                return (i, true);
   136→            }
   137→        }
   138→        return (-1, false);
   139→    }
   140→
   141→    // 살아있는 노드 수 카운트
   142→    func (g: *ReplicaGroup) alive_count() -> i32 {
   143→        let count = 0;
   144→        let i = 0;
   145→        for i = 0; i < g.node_count; i = i + 1 {
   146→            if g.nodes[i].state == REPLICA_ALIVE {
   147→                count = count + 1;
   148→            }
   149→        }
   150→        return count;
   151→    }
   152→
   153→    // === 쿼럼 쓰기/읽기 (핵심) ===
   154→
   155→    // 쿼럼 쓰기: 모든 ALIVE 노드에 쓰고 quorum개 이상 성공 필요
   156→    func (g: *ReplicaGroup) write_quorum(key: string, val: i64) -> (i32, bool) {
   157→        let alive = g.alive_count();
   158→        if alive == 0 {
   159→            return (REP_ERR_NO_ALIVE, false);
   160→        }
   161→
   162→        // 모든 ALIVE 노드에 쓰기
   163→        let acks = 0;
   164→        let i = 0;
   165→        for i = 0; i < g.node_count; i = i + 1 {
   166→            if g.nodes[i].state == REPLICA_ALIVE {
   167→                let ok = g.nodes[i].local_set(key, val);
   168→                if ok {
   169→                    acks = acks + 1;
   170→                }
   171→            }
   172→        }
   173→
   174→        // 쿼럼 확인 (quorum개 이상 성공)
   175→        if acks < g.quorum {
   176→            return (REP_ERR_QUORUM, false);
   177→        }
   178→        return (REP_OK, true);
   179→    }
   180→
   181→    // 쿼럼 읽기: 첫 번째 ALIVE 노드에서 읽기 (단순화)
   182→    func (g: *ReplicaGroup) read_quorum(key: string) -> (i64, bool) {
   183→        let i = 0;
   184→        for i = 0; i < g.node_count; i = i + 1 {
   185→            if g.nodes[i].state == REPLICA_ALIVE {
   186→                return g.nodes[i].local_get(key);
   187→            }
   188→        }
   189→        return (0, false);  // 살아있는 노드 없음
   190→    }
   191→
   192→    // === 내장 KV 스토어 함수 ===
   193→
   194→    // 로컬 Set (배열 기반, 없으면 추가, 있으면 업데이트)
   195→    func (n: *ReplicaNode) local_set(key: string, val: i64) -> bool {
   196→        let i = 0;
   197→        // 기존 키 찾기
   198→        for i = 0; i < n.store_count; i = i + 1 {
   199→            if n.store_keys[i] == key {
   200→                n.store_vals[i] = val;
   201→                return true;
   202→            }
   203→        }
   204→        // 새 키 추가
   205→        if n.store_count >= MAX_KV_PER_NODE {
   206→            return false;  // 스토어 가득 참
   207→        }
   208→        n.store_keys[n.store_count] = key;
   209→        n.store_vals[n.store_count] = val;
   210→        n.store_count = n.store_count + 1;
   211→        return true;
   212→    }
   213→
   214→    // 로컬 Get
   215→    func (n: *ReplicaNode) local_get(key: string) -> (i64, bool) {
   216→        let i = 0;
   217→        for i = 0; i < n.store_count; i = i + 1 {
   218→            if n.store_keys[i] == key {
   219→                return (n.store_vals[i], true);
   220→            }
   221→        }
   222→        return (0, false);
   223→    }
   224→
   225→    // 로컬 Delete
   226→    func (n: *ReplicaNode) local_delete(key: string) -> bool {
   227→        let i = 0;
   228→        let j = 0;
   229→        let found = false;
   230→        for i = 0; i < n.store_count; i = i + 1 {
   231→            if n.store_keys[i] != key {
   232→                n.store_keys[j] = n.store_keys[i];
   233→                n.store_vals[j] = n.store_vals[i];
   234→                j = j + 1;
   235→            } else {
   236→                found = true;
   237→            }
   238→        }
   239→        if found {
   240→            n.store_count = j;
   241→        }
   242→        return found;
   243→    }
   244→
   245→    // 로컬 스토어 크기
   246→    func (n: *ReplicaNode) local_count() -> i32 {
   247→        return n.store_count;
   248→    }
   249→
   250→    // === 하트비트 관리 ===
   251→
   252→    // 하트비트 기록 (응답 받을 때마다 호출)
   253→    func (g: *ReplicaGroup) record_heartbeat(node_id: string, tick: i32) -> bool {
   254→        let i = 0;
   255→        for i = 0; i < g.node_count; i = i + 1 {
   256→            if g.nodes[i].id == node_id {
   257→                g.nodes[i].last_heartbeat = tick;
   258→                return true;
   259→            }
   260→        }
   261→        return false;
   262→    }
   263→
   264→    // 하트비트 체크: 모든 노드의 상태를 업데이트
   265→    // tick 경과에 따라 ALIVE → SUSPECT → DEAD로 전환
   266→    func (g: *ReplicaGroup) heartbeat_check(current_tick: i32) {
   267→        let i = 0;
   268→        for i = 0; i < g.node_count; i = i + 1 {
   269→            let age = current_tick - g.nodes[i].last_heartbeat;
   270→
   271→            // 상태 전환 로직
   272→            if age < SUSPECT_TIMEOUT {
   273→                g.nodes[i].state = REPLICA_ALIVE;
   274→            } else if age < HEARTBEAT_TIMEOUT {
   275→                g.nodes[i].state = REPLICA_SUSPECT;
   276→            } else {
   277→                g.nodes[i].state = REPLICA_DEAD;
   278→            }
   279→        }
   280→    }
   281→
   282→    // === 통계 함수 ===
   283→
   284→    func (g: *ReplicaGroup) group_stats() -> string {
   285→        let alive = g.alive_count();
   286→        let suspect_count = 0;
   287→        let dead_count = 0;
   288→        let i = 0;
   289→        for i = 0; i < g.node_count; i = i + 1 {
   290→            if g.nodes[i].state == REPLICA_SUSPECT {
   291→                suspect_count = suspect_count + 1;
   292→            } else if g.nodes[i].state == REPLICA_DEAD {
   293→                dead_count = dead_count + 1;
   294→            }
   295→        }
   296→        let msg = "[ReplicaGroup] nodes=" + i32_to_string(g.node_count) +
   297→                  " alive=" + i32_to_string(alive) +
   298→                  " suspect=" + i32_to_string(suspect_count) +
   299→                  " dead=" + i32_to_string(dead_count) +
   300→                  " quorum=" + i32_to_string(g.quorum);
   301→        return msg;
   302→    }
   303→
   304→    func (n: *ReplicaNode) node_stats() -> string {
   305→        let state_str = if n.state == REPLICA_ALIVE {
   306→            "ALIVE"
   307→        } else if n.state == REPLICA_SUSPECT {
   308→            "SUSPECT"
   309→        } else {
   310→            "DEAD"
   311→        };
   312→        let msg = "[ReplicaNode] id=" + n.id + " state=" + state_str + " kv=" + i32_to_string(n.store_count);
   313→        return msg;
   314→    }
   315→
   316→    // === 헬퍼 함수 ===
   317→
   318→    @inline
   319→    func i32_to_string(n: i32) -> string {
   320→        if n == 0 { return "0"; }
   321→        if n == 1 { return "1"; }
   322→        if n == 2 { return "2"; }
   323→        if n == 3 { return "3"; }
   324→        if n == 4 { return "4"; }
   325→        if n == 5 { return "5"; }
   326→        if n < 0 { return "-" + i32_to_string(-n); }
   327→        return "?";
   328→    }
   329→}
   330→
   331→// === 테스트 시나리오 (주석) ===
   332→//
   333→// 기본 동작:
   334→//   - group_new(2, 3) → ReplicaGroup{ quorum: 2, factor: 3 }
   335→//   - replica_node_new("node1", "localhost:8001") → ReplicaNode
   336→//   - group.node_add(node1) → true
   337→//
   338→// 쿼럼 쓰기:
   339→//   - 3개 노드 모두 ALIVE:
   340→//     group.write_quorum("key", 100) → (REP_OK, true)
   341→//
   342→//   - 2개 노드 ALIVE, 1개 DEAD:
   343→//     group.write_quorum("key", 200) → (REP_OK, true)  (quorum=2 ≥ 2)
   344→//
   345→//   - 1개 노드 ALIVE, 2개 DEAD:
   346→//     group.write_quorum("key", 300) → (REP_ERR_QUORUM, false)  (1 < 2)
   347→//
   348→// 쿼럼 읽기:
   349→//   - 3개 노드 ALIVE:
   350→//     group.read_quorum("key") → (100, true)
   351→//
   352→//   - 첫 번째 노드만 DEAD, 나머지 ALIVE:
   353→//     group.read_quorum("key") → 두 번째 노드에서 읽음
   354→//
   355→// 하트비트:
   356→//   - group.heartbeat_check(5):
   357→//     age < 3 → ALIVE
   358→//     3 ≤ age < 5 → SUSPECT
   359→//     age ≥ 5 → DEAD
   360→//
