   131→    // 문자열 파싱 (큰따옴표 내 내용)
   132→    func (p: *Parser) parse_string() -> (string, bool) {
   133→        let c = p.peek();
   134→        if c != 34 {  // '"'
   135→            return ("", false);
   136→        }
   137→        p.advance();  // 시작 '"' 스킵
   138→
   139→        let result = "";
   140→        for c = 1; c > 0; {
   141→            c = p.peek();
   142→            if c == -1 {
   143→                return ("", false);  // EOF
   144→            }
   145→            if c == 34 {  // '"'
   146→                p.advance();
   147→                return (result, true);
   148→            }
   149→            // 문자 코드를 문자로 변환 후 추가
   150→            let ch = char_from_code(c);
   151→            result = result + ch;
   152→            p.advance();
   153→        }
   154→        return (result, false);
   155→    }
