   279→    // 값 파싱 (진입점)
   280→    func (p: *Parser) parse_value() -> (JsonValue, bool) {
   281→        p.skip_ws();
   282→        let c = p.peek();
   283→
   284→        if c == 110 {  // 'n' in "null"
   285→            p.advance();  // 간단히: null 스킵
   286→            return (make_null(), true);
   287→        }
   288→        if c == 116 {  // 't' in "true"
   289→            p.advance();
   290→            return (make_bool(true), true);
   291→        }
   292→        if c == 102 {  // 'f' in "false"
   293→            p.advance();
   294→            return (make_bool(false), true);
   295→        }
   296→        if c == 34 {  // '"'
   297→            let s, ok = p.parse_string();
   298→            return (make_string(s), ok);
   299→        }
   300→        if c == 91 {  // '['
   301→            return p.parse_array();
   302→        }
   303→        if c == 123 {  // '{'
   304→            return p.parse_object();
   305→        }
   306→        if c >= 48 && c <= 57 || c == 45 {  // '0'-'9' or '-'
   307→            return p.parse_number();
   308→        }
   309→
   310→        return (make_null(), false);
   311→    }
