   315→    // JSON 문자열 파싱
   316→    func parse(input: string) -> (JsonValue, bool) {
   317→        if len(input) == 0 {
   318→            return (make_null(), false);
   319→        }
   320→        let p = Parser{ input: input, pos: 0, len: len(input) };
   321→        let val, ok = p.parse_value();
   322→        if !ok {
   323→            return (make_null(), false);
   324→        }
   325→        // 파싱 후 남은 텍스트 확인 (선택사항)
   326→        return (val, true);
   327→    }
