   366→    // JsonValue를 들여쓰기와 함께 JSON 문자열로 변환
   367→    func pretty(v: JsonValue) -> string {
   368→        // 간단한 구현: stringify와 동일 (부동소수점 제외하고는 실제 들여쓰기 미구현)
   369→        return stringify(v);
   370→    }
