   372→    // JsonValue에서 점 경로로 값 추출
   373→    // 예: get(v, "a.b.c") → v.a.b.c
   374→    func get(v: JsonValue, path: string) -> (JsonValue, bool) {
   375→        if len(path) == 0 {
   376→            return (v, true);
   377→        }
   378→        if v.kind != KIND_OBJECT {
   379→            return (make_null(), false);
   380→        }
   381→
   382→        // Note: 점 기준 분할 필요 (문자열 처리 미구현)
   383→        // 여기서는 전체 path를 키로 사용 (임시)
   384→        let i = 0;
   385→        for i = 0; i < len(v.object_keys); i = i + 1 {
   386→            if v.object_keys[i] == path {
   387→                return (v.object_vals[i], true);
   388→            }
   389→        }
   390→        return (make_null(), false);
   391→    }
