   393→    // 두 JsonValue 병합 (모두 object여야 함)
   394→    func merge(a: JsonValue, b: JsonValue) -> (JsonValue, bool) {
   395→        if a.kind != KIND_OBJECT || b.kind != KIND_OBJECT {
   396→            return (b, false);
   397→        }
   398→
   399→        let result_keys = make([string], 0);
   400→        let result_vals = make([JsonValue], 0);
   401→
   402→        // a의 모든 키-값 복사
   403→        let i = 0;
   404→        for i = 0; i < len(a.object_keys); i = i + 1 {
   405→            result_keys.push(a.object_keys[i]);
   406→            result_vals.push(a.object_vals[i]);
   407→        }
   408→
   409→        // b의 키-값 추가 또는 덮어쓰기
   410→        for i = 0; i < len(b.object_keys); i = i + 1 {
   411→            let key = b.object_keys[i];
   412→            let val = b.object_vals[i];
   413→            let found = false;
   414→            let j = 0;
   415→            for j = 0; j < len(result_keys); j = j + 1 {
   416→                if result_keys[j] == key {
   417→                    result_vals[j] = val;
   418→                    found = true;
   419→                    j = len(result_keys);  // break
   420→                }
   421→            }
   422→            if !found {
   423→                result_keys.push(key);
   424→                result_vals.push(val);
   425→            }
   426→        }
   427→
   428→        return (JsonValue{
   429→            kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
   430→            array_vals: make([JsonValue], 0), object_keys: result_keys, object_vals: result_vals,
   431→        }, true);
   432→    }
